<?php
declare(strict_types=1);require __DIR__.'/_init.php';$u=api_user();$pdo=db();if($_SERVER['REQUEST_METHOD']==='GET'){$q=$pdo->prepare('SELECT d.id AS deck_id,d.sync_id,d.name,d.updated_at,d.deleted_at,d.revision,c.sync_id AS card_sync_id,c.card_id,c.card_name,c.set_code,c.quantity,c.section_name,c.sort_order FROM decks d LEFT JOIN deck_cards c ON c.deck_id=d.id AND c.deleted_at IS NULL WHERE d.user_id=? ORDER BY d.updated_at ASC,c.section_name ASC,c.sort_order ASC,c.id ASC');$q->execute([$u['id']]);$decks=[];foreach($q->fetchAll() as $r){$sid=$r['sync_id'];if(!isset($decks[$sid]))$decks[$sid]=['sync_id'=>$sid,'name'=>$r['name'],'updated_at'=>$r['updated_at'],'deleted_at'=>$r['deleted_at'],'revision'=>(int)$r['revision'],'cards'=>[]];if($r['card_sync_id'])$decks[$sid]['cards'][]=['sync_id'=>$r['card_sync_id'],'card_id'=>$r['card_id'],'card_name'=>$r['card_name'],'set_code'=>$r['set_code'],'quantity'=>(int)$r['quantity'],'section'=>$r['section_name'],'sort_order'=>(int)$r['sort_order']];}json_response(['ok'=>true,'decks'=>array_values($decks),'server_time'=>gmdate('Y-m-d H:i:s')]);}if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['ok'=>false,'error'=>'method_not_allowed'],405);$d=json_input();$decks=$d['decks']??[];if(!is_array($decks))json_response(['ok'=>false,'error'=>'invalid_payload'],422);$pdo->beginTransaction();try{$upDeck=$pdo->prepare('INSERT INTO decks(user_id,sync_id,name,created_at,updated_at,deleted_at,revision) VALUES(?,?,?,NOW(),NOW(),?,1) ON DUPLICATE KEY UPDATE name=VALUES(name),deleted_at=VALUES(deleted_at),updated_at=NOW(),revision=revision+1');$find=$pdo->prepare('SELECT id FROM decks WHERE user_id=? AND sync_id=? LIMIT 1');$upCard=$pdo->prepare('INSERT INTO deck_cards(deck_id,sync_id,card_id,card_name,set_code,quantity,section_name,sort_order,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE card_id=VALUES(card_id),card_name=VALUES(card_name),set_code=VALUES(set_code),quantity=VALUES(quantity),section_name=VALUES(section_name),sort_order=VALUES(sort_order),deleted_at=NULL,updated_at=NOW()');foreach($decks as $deck){if(!is_array($deck))continue;$sid=trim((string)($deck['sync_id']??''));if($sid==='')continue;$deleted=!empty($deck['deleted_at'])?(string)$deck['deleted_at']:null;$upDeck->execute([$u['id'],substr($sid,0,64),substr((string)($deck['name']??'Deck'),0,120),$deleted]);$find->execute([$u['id'],$sid]);$deckId=(int)$find->fetchColumn();if($deleted){$pdo->prepare('UPDATE deck_cards SET deleted_at=NOW(),updated_at=NOW() WHERE deck_id=?')->execute([$deckId]);continue;}$incoming=[];foreach(($deck['cards']??[]) as $c){if(!is_array($c))continue;$cs=trim((string)($c['sync_id']??''));if($cs==='')continue;$incoming[]=$cs;$section=strtoupper(trim((string)($c['section']??'MAIN')));if(!in_array($section,['MAIN','EXTRA','SIDE'],true))$section='MAIN';$upCard->execute([$deckId,substr($cs,0,64),substr((string)($c['card_id']??''),0,64),substr((string)($c['card_name']??''),0,255),substr((string)($c['set_code']??''),0,80),max(0,(int)($c['quantity']??0)),$section,max(0,(int)($c['sort_order']??0))]);}if($incoming){$ph=implode(',',array_fill(0,count($incoming),'?'));$q=$pdo->prepare("UPDATE deck_cards SET deleted_at=NOW(),updated_at=NOW() WHERE deck_id=? AND sync_id NOT IN ($ph) AND deleted_at IS NULL");$q->execute(array_merge([$deckId],$incoming));}else{$pdo->prepare('UPDATE deck_cards SET deleted_at=NOW(),updated_at=NOW() WHERE deck_id=? AND deleted_at IS NULL')->execute([$deckId]);}}$pdo->commit();}catch(Throwable $e){$pdo->rollBack();json_response(['ok'=>false,'error'=>'database_error'],500);}json_response(['ok'=>true,'server_time'=>gmdate('Y-m-d H:i:s')]);
